function validate([seats]) {
  if (!Array.isArray(seats) || seats.length < 2 || seats.length > 20000) return 'seats needs 2 to 20000 values.';
  if (seats.some(v => v !== 0 && v !== 1)) return 'Every seat is 0 or 1.';
  if (!seats.includes(0)) return 'At least one seat must be free (0).';
  if (!seats.includes(1)) return 'At least one seat must be taken (1).';
  return null;
}

