function maxDistToClosest(seats) {
  const n = seats.length;
  let prev = -1;
  let best = 0;

  for (let i = 0; i < n; i++) {
    if (seats[i] === 0) {
      continue;
    }
    if (prev === -1) {
      best = i;
    } else {
      best = Math.max(best, Math.floor((i - prev) / 2));
    }
    prev = i;
  }
  return Math.max(best, n - 1 - prev);
}

