function maxDistToClosest(seats) {
  // Try every free seat and measure the nearest taken seat directly.
  let answer = 0;
  for (let s = 0; s < seats.length; s++) {
    if (seats[s] !== 0) continue;
    let nearest = Infinity;
    for (let t = 0; t < seats.length; t++) {
      if (seats[t] === 1) nearest = Math.min(nearest, Math.abs(s - t));
    }
    answer = Math.max(answer, nearest);
  }
  return answer;
}

