function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 2 + pick(11);
  const densities = [0.02, 0.1, 0.3, 0.5, 0.9];
  const density = size === 'large' ? densities[pick(densities.length)] : densities[1 + pick(4)];
  const seats = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  // Sometimes leave a long empty stretch at one end so the edge cases are exercised.
  if (rand() < 0.3) {
    const stretch = pick(Math.floor(n / 2) + 1);
    const fromLeft = rand() < 0.5;
    for (let k = 0; k < stretch; k++) seats[fromLeft ? k : n - 1 - k] = 0;
  }
  // The row must have at least one taken and one free seat.
  if (!seats.includes(1)) seats[pick(n)] = 1;
  if (!seats.includes(0)) seats[pick(n)] = 0;
  return [seats];
}
